79	func TestAppendIdenticalReplayIsNoOp(t *testing.T) {
80		index := chain(t,
81			Block{Height: 1, Hash: "h1", Parent: "genesis", Txs: []string{"t1"}},
82			Block{Height: 2, Hash: "h2", Parent: "h1"},
83		)
84		// Empty tx list and missing tx list are the same block.
85		if err := index.Append(Block{Height: 2, Hash: "h2", Parent: "h1", Txs: []string{}}); err != nil {
86			t.Fatalf("identical replay refused: %v", err)
87		}
88		if err := index.Append(Block{Height: 1, Hash: "h1", Parent: "genesis", Txs: []string{"t1"}}); err != nil {
89			t.Fatalf("identical replay of older block refused: %v", err)
90		}
91		if index.Tip != 2 {
92			t.Fatalf("tip moved on replay: %d", index.Tip)
93		}
94		// Same height or hash but different content must fail without overwrite.
95		for _, block := range []Block{
96			{Height: 2, Hash: "h2", Parent: "h1", Txs: []string{"t9"}},
97			{Height: 2, Hash: "h2x", Parent: "h1"},
98			{Height: 1, Hash: "h1", Parent: "other"},
99		} {
100			blocks, byHash, tip := snapshot(index)
101			if err := index.Append(block); err == nil {
102				t.Fatalf("expected refusal of conflicting block %+v", block)
103			}
104			requireUnchanged(t, index, blocks, byHash, tip)
105		}
106		if got := index.Blocks[2]; got.Hash != "h2" || got.Txs != nil {
107			t.Fatalf("stored block overwritten: %+v", got)
108		}
109	}
