265	func TestReorgFailureThenCorrectedRetry(t *testing.T) {
266		index := chain(t,
267			Block{Height: 1, Hash: "h1", Parent: "genesis"},
268			Block{Height: 2, Hash: "h2", Parent: "h1"},
269		)
270		if _, err := index.Reorg([]Block{{Height: 2, Hash: "h2b", Parent: "unknown"}}); err == nil {
271			t.Fatal("expected refusal of unknown ancestor")
272		}
273		dropped, err := index.Reorg([]Block{{Height: 2, Hash: "h2b", Parent: "h1"}})
274		if err != nil {
275			t.Fatalf("corrected retry refused: %v", err)
276		}
277		if !reflect.DeepEqual(dropped, []int64{2}) || index.Tip != 2 || index.Blocks[2].Hash != "h2b" {
278			t.Fatalf("unexpected state after retry: dropped=%v tip=%d", dropped, index.Tip)
279		}
280	}
