282	func TestReorgStoresCopyOfTxs(t *testing.T) {
283		index := chain(t,
284			Block{Height: 1, Hash: "h1", Parent: "genesis"},
285			Block{Height: 2, Hash: "h2", Parent: "h1"},
286		)
287		txs := []string{"t1"}
288		if _, err := index.Reorg([]Block{{Height: 2, Hash: "h2b", Parent: "h1", Txs: txs}}); err != nil {
289			t.Fatal(err)
290		}
291		txs[0] = "mutated"
292		if got := index.Blocks[2].Txs; !reflect.DeepEqual(got, []string{"t1"}) {
293			t.Fatalf("stored txs changed by caller mutation: %v", got)
294		}
295	}
296	
297	func TestConcurrentAppendAndReorg(t *testing.T) {
298		index := chain(t, Block{Height: 1, Hash: "h1", Parent: "genesis"})
299		var wg sync.WaitGroup
300		for worker := 0; worker < 8; worker++ {
301			wg.Add(1)
302			go func(worker int) {
303				defer wg.Done()
304				for i := 0; i < 50; i++ {
305					hash := fmt.Sprintf("w%d-r%d", worker, i)
306					// Every branch is rooted at the known genesis block; most
307					// calls race with each other and either outcome is fine.
308					if _, err := index.Reorg([]Block{{Height: 2, Hash: hash, Parent: "h1"}}); err == nil {
309						// Extend the block just installed; fails harmlessly if
310						// another caller already replaced it.
311						_ = index.Append(Block{Height: 3, Hash: hash + "-x", Parent: hash})
312					}
313				}
314			}(worker)
315		}
316		wg.Wait()
317		// The chain must be fully contiguous with matching parent links, and the
318		// two indexes must agree — the result of some complete serial order.
319		if int64(len(index.Blocks)) != index.Tip || len(index.ByHash) != len(index.Blocks) {
320			t.Fatalf("inconsistent indexes: blocks=%d byHash=%d tip=%d",
321				len(index.Blocks), len(index.ByHash), index.Tip)
322		}
323		for height := int64(2); height <= index.Tip; height++ {
324			block, ok := index.Blocks[height]
325			if !ok {
326				t.Fatalf("gap at height %d (tip=%d)", height, index.Tip)
327			}
328			if block.Parent != index.Blocks[height-1].Hash {
329				t.Fatalf("broken parent link at height %d", height)
330			}
331			if index.ByHash[block.Hash] != height {
332				t.Fatalf("by-hash mismatch at height %d", height)
333			}
334		}
335	}
