	index := txChain(t,
		Block{Height: 1, Hash: "h1", Parent: "genesis", Txs: []string{"t1"}},
	)
	var wg sync.WaitGroup
	stop := make(chan struct{})

	// Ingestion workers: append and reorg concurrently.
	for w := 0; w < 4; w++ {
		wg.Add(1)
		go func(w int) {
			defer wg.Done()
