				select {
				case <-stop:
					return
				default:
				}
				h := fmt.Sprintf("w%d-i%d", w, i)
				if _, err := index.Reorg([]Block{{Height: 2, Hash: h, Parent: "h1", Txs: []string{h}}}); err == nil {
					_ = index.Append(Block{Height: 3, Hash: h + "-x", Parent: h, Txs: []string{h + "-x"}})
				}
			}
		}(w)
	}

	// Query workers: repeatedly page through a fixed range.
	for w := 0; w < 4; w++ {
		wg.Add(1)
		go func(w int) {
			defer wg.Done()
			for i := 0; ; i++ {
				select {
				case <-stop:
					return
				default:
				}
