func TestQueryTxsResubmitCursorSamePage(t *testing.T) {
	blocks := make([]Block, 0, 6)
	for h := int64(1); h <= 6; h++ {
		blocks = append(blocks, Block{Height: h, Hash: fmt.Sprintf("h%d", h), Parent: fmt.Sprintf("h%d", h-1), Txs: []string{fmt.Sprintf("t%d", h)}})
	}
	index := txChain(t, blocks...)
	q := TxQuery{StartHeight: 1, EndHeight: 6, PageSize: 2}
	page1, err := index.QueryTxs(q, "")
	if err != nil {
		t.Fatal(err)
	}
	// Re-submitting the same cursor with the same page size returns the same page.
	page1Again, err := index.QueryTxs(q, page1.Cursor)
	if err != nil {
		t.Fatal(err)
	}
	if !recordsEqual(page1.Records, page1Again.Records) {
		t.Fatalf("page changed on resubmit: %+v vs %+v", page1.Records, page1Again.Records)
	}
	if page1.Cursor != page1Again.Cursor {
		t.Fatalf("next cursor changed on resubmit: %q vs %q", page1.Cursor, page1Again.Cursor)
	}
}

